function subarraySum(nums, k) {
  const seenTotals = new Map([[0, 1]]); // running total -> times seen; 0 = the empty prefix
  let runningTotal = 0;
  let count = 0;
  for (const value of nums) {
    runningTotal += value;
    const needed = runningTotal - k; // an earlier total that would leave exactly k
    count += seenTotals.get(needed) || 0;
    seenTotals.set(runningTotal, (seenTotals.get(runningTotal) || 0) + 1);
  }
  return count;
}

